options.css:
.ems-power-panel {
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  padding: 14px 18px;
  display: flex;
  flex-direction: column;
  font-family: 'Roboto', 'Noto Sans TC', sans-serif;
  color: #d8d9da;
  cursor: pointer;
}
.ems-power-panel:hover {
  background: #ffffff08;
}
.top {
  position: relative;
  flex: 0 0 58%;
  min-height: 0;
}
.trend-chart {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}
.top-content {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: flex-end;
}
.label {
  align-self: flex-start;
  font-size: 14px;
  color: #9fa7b3;
  background: #181b1f50;
  backdrop-filter: blur(1px);
  padding: 2px 8px;
  border-radius: 6px;
}
.main-value {
  align-self: flex-start;
  font-size: 84px;
  font-weight: 500;
  line-height: 1;
  background: #181b1f50;
  backdrop-filter: blur(1px);
  padding: 4px 16px;
}
.unit {
  font-size: 32px;
  font-weight: 400;
  color: #9fa7b3;
  margin-left: 6px;
}
.bottom {
  flex: 0 0 auto;
  display: flex;
  border-top: 1px solid #2c3235;
  margin-top: 8px;
  padding-top: 10px;
}
.stat {
  flex: 1;
  text-align: center;
}
.stat-label {
  font-size: 12px;
  color: #9fa7b3;
}
.stat-value {
  font-size: 32px;
  font-weight: 500;
  margin-top: 2px;
}
.stat-unit {
  font-size: 16px;
  font-weight: 400;
  color: #9fa7b3;
  margin-left: 4px;
}
.stat-sub {
  font-size: 16px;
  color: #6c7580;
}
.divider {
  width: 1px;
  background: #2c3235;
  margin: 2px 0;
}

options.onInit:
function loadECharts() {
  if (window.__echartsModulePromise) return window.__echartsModulePromise;
  window.__echartsModulePromise = import('https://cdn.jsdelivr.net/npm/echarts@5/dist/echarts.esm.min.js');
  return window.__echartsModulePromise;
}

const GRADIENTS = [
  { line: ['#1de9b6', '#00897b'] }, // 電力（本面板使用）：青綠
  { line: ['#00d2ff', '#0066cc'] }, // 水：亮藍
  { line: ['#26c6da', '#006064'] }, // 蒸氣：深青色
  { line: ['#f7971e', '#ff4e50'] }, // 保留：告警/尖峰
];

function buildTrendOption(values, timestamps, peakIndex) {
  const [from, to] = GRADIENTS[0].line;
  const hasPeak = typeof peakIndex === 'number' && peakIndex >= 0 && peakIndex < values.length;

  const markAreaData = hasPeak
    ? [[
        { xAxis: Math.max(peakIndex - 0.4, 0) },
        { xAxis: Math.min(peakIndex + 0.4, values.length - 1) },
      ]]
    : [];

  const markPointData = hasPeak
    ? [{ coord: [peakIndex, values[peakIndex]], value: values[peakIndex] }]
    : [];

  return {
    backgroundColor: 'transparent',
    grid: { left: 0, right: 0, top: 4, bottom: 4 },
    xAxis: { type: 'category', show: false, boundaryGap: false, data: values.map((_, i) => i) },
    yAxis: { type: 'value', show: false, scale: true },
    tooltip: {
      trigger: 'axis',
      backgroundColor: '#1f2329',
      borderColor: '#2c3235',
      textStyle: { color: '#d8d9da', fontSize: 11 },
      formatter: (p) => {
        const point = p?.[0];
        if (!point) return '';
        const ts = timestamps?.[point.dataIndex];
        const timeLabel = ts
          ? new Date(ts).toLocaleTimeString('en-GB', {
              timeZone: 'Asia/Ho_Chi_Minh',
              hour: '2-digit',
              minute: '2-digit',
            })
          : '--:--';
        return `${point.value?.toFixed(2) ?? '--'} kW (${timeLabel})`;
      },
    },
    series: [{
      type: 'line',
      data: values,
      smooth: 0.3,
      symbol: 'none',
      lineStyle: {
        width: 2,
        color: { type: 'linear', x: 0, y: 0, x2: 1, y2: 1, colorStops: [
          { offset: 0, color: from },
          { offset: 1, color: to },
        ] },
      },
      areaStyle: {
        color: { type: 'linear', x: 0, y: 0, x2: 0, y2: 1, colorStops: [
          { offset: 0, color: 'rgba(29, 233, 182, 0.35)' },
          { offset: 1, color: 'rgba(0, 137, 123, 0)' },
        ] },
      }
    }],
  };
}

function animateNumberTo(el, newValue, decimals = 0, duration = 500) {
  if (!el) return;

  const prevValue = parseFloat(el.dataset.rawValue ?? '0') || 0;
  el.dataset.rawValue = newValue;

  if (prevValue === newValue) {
    el.textContent = newValue.toLocaleString(undefined, {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals,
    });
    return;
  }

  if (el.__rollAnimFrame) {
    cancelAnimationFrame(el.__rollAnimFrame);
  }

  const startTime = performance.now();

  function tick(now) {
    const progress = Math.min((now - startTime) / duration, 1);
    const eased = 1 - Math.pow(1 - progress, 3);
    const current = prevValue + (newValue - prevValue) * eased;

    el.textContent = current.toLocaleString(undefined, {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals,
    });

    if (progress < 1) {
      el.__rollAnimFrame = requestAnimationFrame(tick);
    } else {
      el.__rollAnimFrame = null;
    }
  }

  el.__rollAnimFrame = requestAnimationFrame(tick);
}

function renderPanel(props) {
  animateNumberTo(htmlNode.getElementById('total-power-value'), props.totalPower, 2);
  htmlNode.getElementById('today-energy-value').textContent = props.todayEnergy.toLocaleString(undefined, { maximumFractionDigits: 0 });
  htmlNode.getElementById('month-energy-value').textContent = props.monthEnergy.toLocaleString(undefined, { maximumFractionDigits: 0 });
  htmlNode.getElementById('peak-demand-value').textContent = props.peakDemand.toLocaleString(undefined, { maximumFractionDigits: 0 });
  htmlNode.getElementById('peak-demand-time').textContent = props.peakDemandTime;
  if (htmlNode.__trendChart) {
    htmlNode.__trendChart.setOption(buildTrendOption(props.trendData, props.trendTimestamps, props.peakIndex));
  }
}

function bindPanelClick(meterType) {
  const panelRoot = htmlNode.querySelector('.ems-power-panel');
  if (!panelRoot) return;

  panelRoot.onclick = () => {
    getLocationSrv().update({
      query: { 'var-meterType': meterType },
      partial: true,
      replace: true,
    });
  };
}

loadECharts().then((echarts) => {
  if (!htmlNode.__trendChart) {
    htmlNode.__trendChart = echarts.init(htmlNode.getElementById('trend-chart'), null, { renderer: 'svg' });
    let lastW = 0, lastH = 0;
    htmlNode.onpanelupdate = () => {
      const el = htmlNode.getElementById('trend-chart');
      const { width, height } = el.getBoundingClientRect();
      if (width !== lastW || height !== lastH) {
        lastW = width;
        lastH = height;
        htmlNode.__trendChart.resize();
      }
    };
  }
  renderPanel({
    totalPower: 0,
    todayEnergy: 0,
    monthEnergy: 0,
    peakDemand: 0,
    peakDemandTime: '---',
    trendData: [],
    trendTimestamps: [],
    peakIndex: -1,
  });
  bindPanelClick('electricity');
});

