function addArrays(...arrays) {
  const maxLen = Math.max(...arrays.map(arr => arr.length));
  return Array.from({ length: maxLen }, (_, i) =>
    arrays.reduce((sum, arr) => sum + (arr[i] || 0), 0)
  );
}

function findMaxWithTime(values, times) {
  if (!values || values.length === 0) {
    return { maxValue: 0, maxIndex: -1, maxTime: null, maxTimeFormat: '---' };
  }

  const maxIndex = values.reduce((maxIdx, val, i, arr) =>
    val > arr[maxIdx] ? i : maxIdx, 0);

  const maxTime = times?.[maxIndex];

  return {
    maxValue: values[maxIndex] ?? 0,
    maxIndex,
    maxTime: maxTime ?? null,
    maxTimeFormat: maxTime
      ? new Date(maxTime).toLocaleTimeString('en-GB', {
          timeZone: 'Asia/Ho_Chi_Minh',
          hour: '2-digit',
          minute: '2-digit',
        })
      : '---',
  };
}

const getScalarByRefId = (refId, seriesArr, noDataValue = 0) => {
  const s = (seriesArr ?? []).find(item => item.refId === refId);
  const numField = s?.fields?.find(f => f.type === 'number');
  const values = numField?.values ?? [];
  return values.length > 0 ? (values[values.length - 1] ?? noDataValue) : noDataValue;
};

const { series } = data ?? {};
const realtimePower = (series ?? []).find(s => s.refId === 'power');
const seriesPowerTimestamp = realtimePower?.fields
  ?.find(f => f.type === 'time')
  ?.values ?? [];
const seriesPower = realtimePower?.fields
  ?.filter(f => f.type === 'number')
  ?.map(({ values }) => values) ?? [];

const datasetTotalPower = seriesPower.length > 0 ? addArrays(...seriesPower) : [];
const resultMaxDemand = findMaxWithTime(datasetTotalPower, seriesPowerTimestamp);

const liveProps = {
  totalPower: datasetTotalPower.at(-1) ?? 0,
  todayEnergy: getScalarByRefId('today_energy', series, 0),
  monthEnergy: getScalarByRefId('month_energy', series, 0),
  peakDemand: resultMaxDemand.maxValue,
  peakDemandTime: resultMaxDemand.maxTimeFormat,
  trendData: datasetTotalPower,
  trendTimestamps: seriesPowerTimestamp,
  peakIndex: resultMaxDemand.maxIndex,
};

renderPanel(liveProps);

