    const progress = Math.min((now - startTime) / duration, 1);
    const eased = 1 - Math.pow(1 - progress, 3);
    const current = prevValue + (newValue - prevValue) * eased;

    el.textContent = current.toLocaleString(undefined, {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals,
    });

    if (progress < 1) {
      el.__rollAnimFrame = requestAnimationFrame(tick);
    } else {
      el.__rollAnimFrame = null;
    }
  }

  el.__rollAnimFrame = requestAnimationFrame(tick);
}

function renderPanel(props) {
  animateNumberTo(htmlNode.getElementById('total-water-value'), props.totalFlow, 2);
  htmlNode.getElementById('today-water-value').textContent = props.todayWater.toLocaleString(undefined, { maximumFractionDigits: 0 });
  htmlNode.getElementById('month-water-value').textContent = props.monthWater.toLocaleString(undefined, { maximumFractionDigits: 0 });
  htmlNode.getElementById('peak-flow-value').textContent = props.peakFlow.toLocaleString(undefined, { maximumFractionDigits: 0 });
  htmlNode.getElementById('peak-flow-time').textContent = props.peakFlowTime;
  if (htmlNode.__trendChart) {
    htmlNode.__trendChart.setOption(buildTrendOption(props.trendData, props.trendTimestamps));
  }
