function addArrays(...arrays) {
  const maxLen = Math.max(...arrays.map(arr => arr.length));
  return Array.from({ length: maxLen }, (_, i) =>
    arrays.reduce((sum, arr) => sum + (arr[i] || 0), 0)
  );
}

function findMaxWithTime(values, times) {
  if (!values || values.length === 0) {
    return { maxValue: 0, maxIndex: -1, maxTime: null, maxTimeFormat: '---' };
  }

  const maxIndex = values.reduce((maxIdx, val, i, arr) =>
    val > arr[maxIdx] ? i : maxIdx, 0);

  const maxTime = times?.[maxIndex];

  return {
    maxValue: values[maxIndex] ?? 0,
    maxIndex,
    maxTime: maxTime ?? null,
    maxTimeFormat: maxTime
      ? new Date(maxTime).toLocaleTimeString('en-GB', {
          timeZone: 'Asia/Ho_Chi_Minh',
          hour: '2-digit',
          minute: '2-digit',
        })
      : '---',
  };
}

const getScalarByRefId = (refId, seriesArr, noDataValue = 0) => {
  const s = (seriesArr ?? []).find(item => item.refId === refId);
  const numField = s?.fields?.find(f => f.type === 'number');
  const values = numField?.values ?? [];
  return values.length > 0 ? (values[values.length - 1] ?? noDataValue) : noDataValue;
};

