  ?.find(f => f.type === 'time')
  ?.values ?? [];
const seriesFlow = realtimeFlow?.fields
  ?.filter(f => f.type === 'number')
  ?.map(({ values }) => values) ?? [];

const datasetTotalFlow = seriesFlow.length > 0 ? addArrays(...seriesFlow) : [];
const resultPeakFlow = findMaxWithTime(datasetTotalFlow, seriesFlowTimestamp);

const liveProps = {
