options.onInit:
function loadECharts() {
  if (window.__echartsModulePromise) return window.__echartsModulePromise;
  window.__echartsModulePromise = import('https://cdn.jsdelivr.net/npm/echarts@5/dist/echarts.esm.min.js');
  return window.__echartsModulePromise;
}

const GRADIENTS = [
  { line: ['#1de9b6', '#00897b'] }, // 電力：青綠
  { line: ['#00d2ff', '#0066cc'] }, // 水：亮藍
  { line: ['#26c6da', '#006064'] }, // 蒸氣（本面板使用）：深青色
  { line: ['#f7971e', '#ff4e50'] }, // 保留：告警/尖峰
];

const METER_IDS = ['S-DYE1', 'S-BOIL', 'S-DYE2'];

function buildTrendOption(values, timestamps, peakIndex) {
  const [from, to] = GRADIENTS[2].line;
  const hasPeak = typeof peakIndex === 'number' && peakIndex >= 0 && peakIndex < values.length;

  const markAreaData = hasPeak
    ? [[
        { xAxis: Math.max(peakIndex - 0.4, 0) },
        { xAxis: Math.min(peakIndex + 0.4, values.length - 1) },
      ]]
    : [];

  const markPointData = hasPeak
    ? [{ coord: [peakIndex, values[peakIndex]], value: values[peakIndex] }]
    : [];

  return {
    backgroundColor: 'transparent',
    grid: { left: 0, right: 0, top: 4, bottom: 4 },
    xAxis: { type: 'category', show: false, boundaryGap: false, data: values.map((_, i) => i) },
    yAxis: { type: 'value', show: false, scale: true },
    tooltip: {
      trigger: 'axis',
      backgroundColor: '#1f2329',
      borderColor: '#2c3235',
      textStyle: { color: '#d8d9da', fontSize: 11 },
      formatter: (p) => {
        const point = p?.[0];
        if (!point) return '';
        const ts = timestamps?.[point.dataIndex];
        const timeLabel = ts
          ? new Date(ts).toLocaleTimeString('en-GB', {
              timeZone: 'Asia/Ho_Chi_Minh',
              hour: '2-digit',
              minute: '2-digit',
            })
          : '--:--';
        return `${point.value?.toFixed(2) ?? '--'} kg/h (${timeLabel})`;
      },
    },
    series: [{
      type: 'line',
      data: values,
      smooth: 0.3,
      symbol: 'none',
      lineStyle: {
        width: 2,
        color: { type: 'linear', x: 0, y: 0, x2: 1, y2: 1, colorStops: [
          { offset: 0, color: from },
          { offset: 1, color: to },
        ] },
      },
      areaStyle: {
        color: { type: 'linear', x: 0, y: 0, x2: 0, y2: 1, colorStops: [
          { offset: 0, color: 'rgba(38, 198, 218, 0.35)' },
          { offset: 1, color: 'rgba(0, 96, 100, 0)' },
        ] },
      }
    }],
  };
}

function animateNumberTo(el, newValue, decimals = 0, duration = 500) {
  if (!el) return;

  const prevValue = parseFloat(el.dataset.rawValue ?? '0') || 0;
  el.dataset.rawValue = newValue;

  if (prevValue === newValue) {
    el.textContent = newValue.toLocaleString(undefined, {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals,
    });
    return;
  }

  if (el.__rollAnimFrame) {
    cancelAnimationFrame(el.__rollAnimFrame);
  }

  const startTime = performance.now();

  function tick(now) {
    const progress = Math.min((now - startTime) / duration, 1);
    const eased = 1 - Math.pow(1 - progress, 3);
    const current = prevValue + (newValue - prevValue) * eased;

    el.textContent = current.toLocaleString(undefined, {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals,
    });

    if (progress < 1) {
      el.__rollAnimFrame = requestAnimationFrame(tick);
    } else {
      el.__rollAnimFrame = null;
    }
  }

  el.__rollAnimFrame = requestAnimationFrame(tick);
}

const getMeterSnapshot = (meterId, snapshotSeries) => {
  const fields = snapshotSeries?.fields ?? [];
  const meterIdField = fields.find(f => f.name === 'meter_id');
  const flowField = fields.find(f => f.name === 'flow_rate_kgh');
  const pressureField = fields.find(f => f.name === 'pressure_bar');
  const tempField = fields.find(f => f.name === 'temperature_c');

  const idx = meterIdField?.values?.findIndex(v => v === meterId) ?? -1;
  if (idx === -1) {
    return { flow: 0, pressure: 0, temp: 0 };
  }

  return {
    flow: flowField?.values?.[idx] ?? 0,
    pressure: pressureField?.values?.[idx] ?? 0,
    temp: tempField?.values?.[idx] ?? 0,
  };
};

function renderPanel(props) {
  animateNumberTo(htmlNode.getElementById('total-flow-value'), props.totalFlow, 0);

  props.meters.forEach(({ meterId, flow, pressure, temp }) => {
    const col = htmlNode.querySelector(`.meter-col[data-meter="${meterId}"]`);
    if (!col) return;
    col.querySelector('.flow-value').textContent = flow.toLocaleString(undefined, { maximumFractionDigits: 1 });
    col.querySelector('.pressure-value').textContent = pressure.toLocaleString(undefined, { maximumFractionDigits: 2 });
    col.querySelector('.temp-value').textContent = temp.toLocaleString(undefined, { maximumFractionDigits: 1 });
  });

  if (htmlNode.__trendChart) {
    htmlNode.__trendChart.setOption(buildTrendOption(props.trendData, props.trendTimestamps, props.peakIndex));
  }
}

loadECharts().then((echarts) => {
  if (!htmlNode.__trendChart) {
    htmlNode.__trendChart = echarts.init(htmlNode.getElementById('trend-chart'), null, { renderer: 'svg' });
    htmlNode.onpanelupdate = () => htmlNode.__trendChart.resize();
  }
  renderPanel({
    totalFlow: 0,
    trendData: [],
    trendTimestamps: [],
    peakIndex: -1,
    meters: METER_IDS.map(meterId => ({ meterId, flow: 0, pressure: 0, temp: 0 })),
  });
});

