// ── 依 meterType 決定單位 ──────────────────────────
const meterType = context.grafana.replaceVariables('$meterType');

const UNIT_MAP = {
  electricity: { unit: 'kWh', title: '用電佔比', emptyText: '無用電紀錄' },
  water: { unit: 'm³', title: '用水佔比', emptyText: '無用水紀錄' },
  steam: { unit: 't', title: '用汽佔比', emptyText: '無用汽紀錄' },
};
const { unit, title, emptyText } = UNIT_MAP[meterType] || { unit: '', title: '佔比', emptyText: '無資料' };

// ── 組資料 + 過濾 0 值 + 排序 ──────────────────────
let pieData = context.panel.data.series.flatMap(frame =>
  frame.fields.map(f => ({
    name: f.labels?.description || f.name,
    value: parseFloat(f.values[0].toFixed(2))
  }))
).filter(d => d.value > 0)
  .sort((a, b) => b.value - a.value);

// ── Top N + 其他聚合 ────────────────────────────────
const TOP_N = 7;
if (pieData.length > TOP_N) {
  const top = pieData.slice(0, TOP_N);
  const restSum = pieData.slice(TOP_N).reduce((sum, d) => sum + d.value, 0);
  pieData = [...top, { name: '其他', value: parseFloat(restSum.toFixed(2)) }];
}

// ── 全為 0 / 無資料時顯示空狀態 ──────────────────────
if (pieData.length === 0) {
  return {
    backgroundColor: 'transparent',
    title: [{
      text: emptyText,
      left: '41.5%',
      top: '52%',
      textAlign: 'center',
      textStyle: { color: '#555c6a', fontSize: 16 }
    }],
    series: [{
      type: 'pie',
      radius: ['42%', '68%'],
